// JVM flags for container-optimized environments
// -XX:MaxRAMPercentage=75.0 ensures the heap doesn't consume all container memory
// -XX:+UseContainerSupport is enabled by default in Java 10+

public class ContainerConfig {
    public static void main(String[] args) {
        // Example of reading container limits inside the JVM
        long maxMemory = Runtime.getRuntime().maxMemory();
        System.out.println("JVM Max Heap configured for container: " + (maxMemory / 1024 / 1024) + " MB");
    }
}
